# Illustrative, SDK-free model of the client lifecycle.
class FakeServer:
    def handle(self, method, params):
        if method == "initialize":
            return {"protocolVersion": "1.0", "capabilities": {"tools": True}}
        if method == "tools/list":
            return {"tools": [{"name": "add", "description": "add two ints",
                               "inputSchema": {"type": "object"}}]}
        if method == "tools/call":
            a, b = params["arguments"]["a"], params["arguments"]["b"]
            return {"content": [{"type": "text", "text": str(a + b)}]}
        raise ValueError("unknown method")

class Client:
    def __init__(self, server):
        self.server = server
        self.ready = False
    def initialize(self):
        info = self.server.handle("initialize", {})
        self.ready = True                 # handshake done
        return info
    def _require_ready(self):
        if not self.ready:
            raise RuntimeError("call initialize() before using the session")
    def list_tools(self):
        self._require_ready()
        return self.server.handle("tools/list", {})["tools"]
    def call_tool(self, name, arguments):
        self._require_ready()
        res = self.server.handle("tools/call", {"name": name, "arguments": arguments})
        return res["content"][0]["text"]

client = Client(FakeServer())
client.initialize()                       # 1) handshake
tools = client.list_tools()               # 2) discover
print("discovered:", tools[0]["name"])
print("result:", client.call_tool("add", {"a": 2, "b": 3}))  # 3) call

# A mock model + client to show where MCP plugs into the agent loop.
class MockClient:
    def list_tools(self):
        return [{"name": "get_price", "description": "price of a ticker",
                 "input_schema": {"type": "object"}}]
    def call_tool(self, name, args):
        prices = {"ACME": 42.0}
        return str(prices[args["ticker"]])

def mock_llm(history, tools):
    # step 1: ask for the tool; step 2: finish with an answer
    if not any(m["role"] == "tool" for m in history):
        return {"done": False, "tool": "get_price", "args": {"ticker": "ACME"}}
    price = next(m["content"] for m in history if m["role"] == "tool")
    return {"done": True, "answer": f"ACME trades at ${price}"}

client = MockClient()
model_tools = client.list_tools()          # discover -> advertise to model
history = [{"role": "user", "content": "What is ACME trading at?"}]
for _ in range(5):                          # bounded loop
    step = mock_llm(history, tools=model_tools)   # reason
    if step["done"]:
        print(step["answer"]); break
    result = client.call_tool(step["tool"], step["args"])   # act via MCP
    history.append({"role": "tool", "content": result})     # observe

