class MiniClient:
    def __init__(self, server):
        self.server = server
        self.ready = False

    def initialize(self):
        info = self.server.handle("initialize", {})
        self.ready = True          # handshake complete
        return info

    def _require_ready(self):
        if not self.ready:
            raise RuntimeError("not initialized")

    def list_tools(self):
        self._require_ready()
        return self.server.handle("tools/list", {})["tools"]

    def call_tool(self, name, arguments):
        self._require_ready()
        res = self.server.handle(
            "tools/call", {"name": name, "arguments": arguments}
        )
        return res["content"][0]["text"]

