class Server:
    def handle(self, method, params):
        if method == "initialize":
            return {"protocolVersion": "1.0"}
        if method == "tools/list":
            return {"tools": [{"name": "ping"}]}
        if method == "tools/call":
            return {"content": [{"type": "text", "text": "pong:" + params["arguments"]["x"]}]}
        raise ValueError(method)

c = MiniClient(Server())

# calling before initialize must fail
try:
    c.list_tools()
    raise AssertionError("should have raised")
except RuntimeError:
    pass

info = c.initialize()
assert info["protocolVersion"] == "1.0"
assert c.list_tools()[0]["name"] == "ping"
assert c.call_tool("ping", {"x": "hi"}) == "pong:hi"
print("all tests passed")

