def to_model_tools(discovered):
    # MCP tool -> provider tool schema (provider-specific field names).
    return [
        {"name": t["name"],
         "description": t.get("description", ""),
         "parameters": t.get("input_schema", {"type": "object"})}
        for t in discovered
    ]

def run_turn(model_fn, client, history):
    tools = to_model_tools(client.list_tools())
    step = model_fn(history, tools)          # reason
    if step.get("done"):
        return {"done": True, "answer": step["answer"]}
    # act: execute the chosen tool through the MCP client
    result_text = client.call_tool(step["tool"], step["args"])
    # observe: hand back an observation the caller appends to history
    return {"done": False, "observation": {"role": "tool", "content": result_text}}

if __name__ == "__main__":
    class C:
        def list_tools(self):
            return [{"name": "sq", "description": "square n", "input_schema": {}}]
        def call_tool(self, name, args):
            return str(args["n"] ** 2)
    def model(history, tools):
        return {"done": False, "tool": "sq", "args": {"n": 5}}
    print(run_turn(model, C(), [{"role": "user", "content": "square 5"}]))
